import{Port}from'../../core/index.js';import{THREE,box,solid,roundedRect,plastic,metal,frame,portQuaternion,wire}from'./geometry.js';import{spec}from'./dimensions.js';
export function addPort(host,id,connector,at,face,size,pins=[]){return host.add(new Port({id,label:'PoE CAM-W v1.1 '+id+' · mechanical connector',connector,position:at,quaternion:portQuaternion(face),hitSize:[size[0],1,size[1]],pins,meta:{role:'visual-connector',face,scope:'Actual physical mating/attachment only;no power,GPIO,UART,download,PoE,ethernet or firmware behavior.'}}));}
export function grove(host){const g=frame(host.body,'PoE CAM-W v1.1 actual top white HY2.0-4P',spec.grove.position,'top'),m=plastic(0xe9e9dd),contacts=[],walls=[];for(const x of[-4.65,4.65])walls.push(box(g,[.7,5.1,6.4],[x,0,-3.2],m,'PoE CAM-W Grove side wall'));walls.push(box(g,[8.6,.65,6.4],[0,-2.225,-3.2],m,'PoE CAM-W Grove floor'),box(g,[8.6,4.45,.65],[0,.325,-6.075],m,'PoE CAM-W Grove actual deep backstop'),box(g,[4.8,.45,2.7],[0,2.325,-4.7],m,'PoE CAM-W Grove latch bridge'));for(const x of[-3.8,3.8])walls.push(box(g,[.7,.55,1.25],[x,2.275,-1.8],m,'PoE CAM-W Grove shoulder'));for(let i=0;i<4;i++){contacts.push(box(g,[.42,.42,4.6],[(i-1.5)*2,.15,-3.6],metal(0xc2ad76),'PoE CAM-W Grove real contact '+(i+1)));box(g,[.42,1.6,.42],[(i-1.5)*2,-2.8,-5.7],metal(),'PoE CAM-W Grove retained solder tail');}return{group:g,walls,contacts,port:addPort(host,'grove','grove',spec.grove.position,'top',[10,5.1],['GND','5V','G25','G33'].map((name,i)=>({n:i+1,name,color:['black','red','yellow','white'][i]})))};}
function rjMouth(){const s=new THREE.Path();s.moveTo(-5.8,4.2);s.lineTo(5.8,4.2);s.lineTo(5.8,-2.8);s.lineTo(3.2,-2.8);s.lineTo(3.2,-3.7);s.lineTo(2.2,-3.7);s.lineTo(2.2,-4.2);s.lineTo(-2.2,-4.2);s.lineTo(-2.2,-3.7);s.lineTo(-3.2,-3.7);s.lineTo(-3.2,-2.8);s.lineTo(-5.8,-2.8);s.closePath();return s;}
export function ethernet(host){const g=frame(host.body,'PoE CAM-W v1.1 actual bottom8P8C RJ45',spec.ethernet.position,'bottom'),s=roundedRect(15.2,11.8,.15);s.holes.push(rjMouth());const shield=solid(g,s,.28,[0,0,-.28],metal(),'PoE CAM-W RJ45 actual shield mouth with real keyed bore'),carrier=solid(g,s,17.8,[0,0,-18.0],plastic(),'PoE CAM-W RJ45 genuinely deep insulating carrier'),stop=box(g,[11.55,8.2,.55],[0,.05,-17.85],plastic(),'PoE CAM-W RJ45 deep insertion stop'),contacts=[];for(const x of[-7.5,7.5])box(g,[.2,11.6,17.5],[x,0,-9.0],metal(),'PoE CAM-W RJ45 real folded shield side');for(const y of[-5.8,5.8])box(g,[14.8,.2,17.5],[0,y,-9.0],metal(),'PoE CAM-W RJ45 folded shield roof');for(let i=0;i<8;i++){const x=(i-3.5)*1.016;contacts.push([wire(g,[x,3.9,-1.5],[x,2.3,-7.5],.115,metal(0xc4aa69),'PoE CAM-W RJ45 spring contact '+(i+1)),wire(g,[x,2.3,-7.5],[x,3.8,-16.8],.115,metal(0xc4aa69),'PoE CAM-W RJ45 retained contact tail '+(i+1))]);}return{group:g,shield,carrier,stop,contacts,port:addPort(host,'ethernet','rj45-8p8c',spec.ethernet.position,'bottom',[15.2,11.8],Array.from({length:8},(_,i)=>({n:i+1,name:'physical contact '+(i+1)})))};}
export function service(host,id,info){const g=frame(host.body,'PoE CAM-W v1.1 actual '+id+' back female socket',info.position,'back'),s=roundedRect(3.45,8.2,.12),sites=[];for(let i=0;i<3;i++){const y=(i-1)*2.54;s.holes.push(roundedRect(1.3,1.3,.035,{cx:0,cy:y,path:new THREE.Path(),clockwise:true}));sites.push([0,y]);}const carrier=solid(g,s,4.9,[0,0,-4.9],plastic(0x141915),'PoE CAM-W '+id+' actual3square bores carrier'),contacts=[],floors=[];for(const[x,y]of sites){floors.push(box(g,[1.29,1.29,.13],[x,y,-4.75],plastic(),'PoE CAM-W '+id+' recessed socket floor'));for(const sign of[-1,1])contacts.push(box(g,[.13,.8,1.8],[x+sign*.47,y,-2.4],metal(0xbba970),'PoE CAM-W '+id+' real recessed spring'));box(g,[.45,.45,1.35],[x,y,-5.5],metal(),'PoE CAM-W '+id+' retained square solder tail');}const port=addPort(host,id,info.connector,info.position,'back',[3.45,8.2],info.pins.map((name,i)=>({n:i+1,name})));port.meta.visualTopToBottom=id==='download-p2'?['GND','G0','EN']:['3V3','TX','RX'];port.meta.pinNumberSource='Own P2/P3 schematic numbering;mechanical metadata only';return{group:g,carrier,contacts,floors,sites,port};}
